WITH flattened_attrs AS (SELECT id, log_ts, level, latency_ms, status_code, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version, SIZE(context) AS num_context FROM app_logs) SELECT id, level, latency_ms, status_code, duration_sec, retry_count, has_version, num_context, SUM(retry_count) OVER (PARTITION BY level) level_sum_retry_count, RANK() OVER (PARTITION BY level ORDER BY latency_ms DESC NULLS LAST) latency_ms_rank, FIRST_VALUE(num_context) IGNORE NULLS OVER (PARTITION BY level ORDER BY status_code, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_num_context, ROW_NUMBER() OVER (PARTITION BY level ORDER BY latency_ms DESC, id) row_seq, AVG(latency_ms) OVER (PARTITION BY level) level_avg_latency_ms FROM flattened_attrs
